const std=@import("std");const host=@import("machine.zig");const F=host.Fixture;const c=host.c;const gm=@cImport({@cInclude("graphics_color_model.h");});
pub fn word(f:*F,at:u16,v:u16)void{f.poke(at,@truncate(v));f.poke(at+1,@truncate(v>>8));}
pub fn init()!F{var f=try F.init();errdefer f.deinit();c.dos64_enable_reu(f.machine);_=try f.call("dos64_overlay_init",10000);f.poke(try f.symbol("dos64_overlay_reu_mib"),4);const b=try f.call("dos64_overlay_bootstrap",1000000);try std.testing.expectEqual(@as(u8,0),b.p&1);f.poke(try f.symbol("dos64_cache_limit"),2);_=try f.call("dos64_cache_init",50000);_=try f.call("dos64_cpu_init",10000);_=try f.call("dos64_io_init",10000);return f;}
pub fn io(f:*F,read:bool,port:u16,width:u8,value:u16,ok:bool)!u16{word(f,try f.symbol("dos64_io_port"),port);word(f,try f.symbol("dos64_io_value"),value);f.poke(try f.symbol("dos64_io_width"),width);const g=try f.symbol("dos64_guest");var before:[28]u8=undefined;for(&before,0..)|*v,i|v.*=f.peek(g+@as(u16,@intCast(i)));const result=try f.call(if(read)"dos64_io_read"else "dos64_io_write",10000);try std.testing.expectEqual(@as(u8,@intFromBool(!ok)),result.p&1);try std.testing.expectEqual(f.initial_status&0xce,result.p&0xce);try std.testing.expectEqual(port,f.word(try f.symbol("dos64_io_port")));try std.testing.expectEqual(width,f.peek(try f.symbol("dos64_io_width")));for(before,0..)|v,i|try std.testing.expectEqual(v,f.peek(g+@as(u16,@intCast(i))));const got=f.word(try f.symbol("dos64_io_value"));if(!read or !ok)try std.testing.expectEqual(value,got);return got;}
fn select(f:*F,n:u8)!void{_=try io(f,false,0x3d4,0,n,true);}
fn reg(f:*F,off:u16,v:u16)!void{word(f,(try f.symbol("dos64_guest"))+off,v);}
pub fn video(f:*F,ax:u16,bx:u16,cx:u16,dx:u16)!void{try reg(f,0,ax);try reg(f,6,bx);try reg(f,2,cx);try reg(f,4,dx);const r=try f.call("dos64_video_service",30000000);try std.testing.expectEqual(@as(u8,0),r.p&1);}

test "originalCGA all mirrored index data pairs honor5bit selector masks readonly lightpen and writeonly reads"{
 var f=try init();defer f.deinit();const regs=try f.symbol("dos64_cga_registers");const masks=[_]u8{255,255,255,15,127,31,127,127,3,31,127,31,63,255,63,255};
 for(0..4)|alias|{const port:u16=0x3d0+@as(u16,@intCast(alias*2));for(0..32)|n|{_=try io(&f,false,port,0,@as(u16,@intCast(n))|0x80,true);try std.testing.expectEqual(@as(u8,@intCast(n)),f.peek(try f.symbol("dos64_cga_index")));_=try io(&f,false,port+1,0,0xff,true);if(n<16)try std.testing.expectEqual(masks[n],f.peek(regs+@as(u16,@intCast(n))));const readable=n>=14 and n<18;const got=try io(&f,true,port+1,0,0xa55a,readable);if(readable)try std.testing.expectEqual(@as(u16,0xa500)|@as(u16,if(n<16)masks[n]else 0),got);_=try io(&f,true,port,0,0x695a,false);}}
}
test "CGA wordwrite preflight is atomic at3D7 boundary while odd and even aliases preserve descriptor order"{
 var f=try init();defer f.deinit();const regs=try f.symbol("dos64_cga_registers");_=try io(&f,false,0x3d4,1,0x9e0f,true);try std.testing.expectEqual(@as(u8,15),f.peek(try f.symbol("dos64_cga_index")));try std.testing.expectEqual(@as(u8,0x9e),f.peek(regs+15));_=try io(&f,false,0x3d5,1,0x0e47,true);try std.testing.expectEqual(@as(u8,14),f.peek(try f.symbol("dos64_cga_index")));try std.testing.expectEqual(@as(u8,0x47),f.peek(regs+15));
 for([_]u16{0x3cf,0x3d7,0x3d8,0x13d4,0xffff})|port|{const index=f.peek(try f.symbol("dos64_cga_index"));const before=f.peek(regs+14);_=try io(&f,false,port,1,0xff0f,false);try std.testing.expectEqual(index,f.peek(try f.symbol("dos64_cga_index")));try std.testing.expectEqual(before,f.peek(regs+14));}
 for(0..8)|n|_=try io(&f,true,0x3d0+@as(u16,@intCast(n)),1,0x369a,false);_=try io(&f,false,0x3d4,2,0xffff,false);
}
test "CGA resident gates reject absent extension before access and preserve all256 caller statuses"{
 var f=try init();defer f.deinit();for(0..256)|status|{f.initial_status=@intCast(status);_=try io(&f,false,0x3d4,1,0x560f,true);try std.testing.expectEqual(@as(u16,0xa556),try io(&f,true,0x3d5,0,0xa500,true));_=try io(&f,true,0x3d4,0,0x9988,false);}f.poke(try f.symbol("hdb_extension_ready"),0);const old=f.peek(try f.symbol("dos64_cga_index"));_=try io(&f,false,0x3d4,0,2,false);try std.testing.expectEqual(old,f.peek(try f.symbol("dos64_cga_index")));_=try io(&f,true,0x21,0,0xaa00,true);
}
test "BIOSmode cursor inactivepage shape and activepage program actualCGA latches while hardwarewrites leaveBDA softwarecursor"{
 var f=try init();defer f.deinit();const rr=try f.symbol("dos64_cga_registers");try video(&f,3,0,0,0);try std.testing.expectEqual(@as(u8,0x71),f.peek(rr));try std.testing.expectEqual(@as(u8,0x50),f.peek(rr+1));try video(&f,0x0200,0,0,0x0607);try std.testing.expectEqual(@as(u8,1),f.peek(rr+14));try std.testing.expectEqual(@as(u8,0xe7),f.peek(rr+15));try video(&f,0x0200,0x100,0,0x0304);try std.testing.expectEqual(@as(u8,0xe7),f.peek(rr+15));try video(&f,0x0501,0,0,0);try std.testing.expectEqual(@as(u8,8),f.peek(rr+12));try std.testing.expectEqual(@as(u8,0),f.peek(rr+13));try std.testing.expectEqual(@as(u8,8),f.peek(rr+14));try std.testing.expectEqual(@as(u8,0xf4),f.peek(rr+15));try video(&f,0x0100,0,0x7f3f,0);try std.testing.expectEqual(@as(u8,0x7f),f.peek(rr+10));try std.testing.expectEqual(@as(u8,0x1f),f.peek(rr+11));_=try io(&f,false,0x3d4,1,0x660f,true);try video(&f,0x0300,0x100,0,0);try std.testing.expectEqual(@as(u16,0x0304),f.word((try f.symbol("dos64_guest"))+4));try std.testing.expectEqual(@as(u8,0x66),f.peek(rr+15));try video(&f,1,0,0,0);try std.testing.expectEqual(@as(u8,0x38),f.peek(rr));try video(&f,6,0,0,0);try std.testing.expectEqual(@as(u8,0x7f),f.peek(rr+4));try std.testing.expectEqual(@as(u8,1),f.peek(rr+9));
}
test "exact originalTURBO CRTCcursor probe executes OUT IN66 comparison restore without vendorpatch"{
 for([_]u16{0x3d4,0x3b4})|port|{var f=try init();defer f.deinit();const bytes=[_]u8{0xee,0x42,0xec,0x50,0xb0,0x66,0xee,0xb9,0x00,0x01,0xe2,0xfe,0xec,0x3c,0x66,0x58,0xee,0x58,0xc3};const regs=try f.symbol("dos64_cga_registers");f.poke(regs+15,0x29);try reg(&f,0,15);try reg(&f,4,port);try reg(&f,8,0x8000);try reg(&f,18,0x394d);try reg(&f,20,0x3000);try reg(&f,24,0xe);try reg(&f,26,0xf246);for(bytes,0..)|v,i|c.dos64_reu_poke(f.machine,0x394de + @as(u32,@intCast(i)),v);c.dos64_reu_poke(f.machine,0x38000,0xef);c.dos64_reu_poke(f.machine,0x38001,0xbe);var n:usize=0;const g=try f.symbol("dos64_guest");while(f.word(g+24)!=0x20 and n<600):(n+=1){const r=try f.call("dos64_cpu_step",100000);try std.testing.expectEqual(@as(u8,0),r.p&1);}try std.testing.expectEqual(@as(u16,0x20),f.word(g+24));try std.testing.expectEqual(@as(u8,0x29),f.peek(regs+15));try std.testing.expectEqual(@as(u16,0xbeef),f.word(g));try std.testing.expectEqual(port+1,f.word(g+4));try std.testing.expectEqual(@as(u16,0x8002),f.word(g+8));try std.testing.expectEqual(@as(u16,if(port==0x3d4)0x40 else 0),f.word(g+26)&0x40);try std.testing.expectEqual(@as(u16,0),f.word(g+26)&1);try std.testing.expect(n>250);}
}

test "absentMDA byteports returnFF ignorewrites and preserve everyCGA latch BIOSBDA and neighboringfailclosed ports"{
 var f=try init();defer f.deinit();const rr=try f.symbol("dos64_cga_registers");const idx=try f.symbol("dos64_cga_index");for(0..18)|i|f.poke(rr+@as(u16,@intCast(i)),@truncate(i*13));f.poke(idx,15);for(0..256)|i|c.dos64_reu_poke(f.machine,0x400+@as(u32,@intCast(i)),@truncate(i*19));
 for([_]u16{0x3b4,0x3b5})|port|{_=try io(&f,false,port,0,0x66,true);try std.testing.expectEqual(@as(u16,0xa5ff),try io(&f,true,port,0,0xa500,true));_=try io(&f,false,port,1,0x6666,false);_=try io(&f,true,port,1,0x1234,false);}
 for([_]u16{0x3b3,0x3b6,0x3b8,0x13b4,0x3da})|port|{_=try io(&f,true,port,0,0x1234,false);_=try io(&f,false,port,0,0x66,false);}
 for(0..18)|i|try std.testing.expectEqual(@as(u8,@truncate(i*13)),f.peek(rr+@as(u16,@intCast(i))));try std.testing.expectEqual(@as(u8,15),f.peek(idx));for(0..256)|i|try std.testing.expectEqual(@as(u8,@truncate(i*19)),c.dos64_reu_peek(f.machine,0x400+@as(u32,@intCast(i))));
}
pub fn busWrite(f:*F,at:u32,v:u8)!void{const a=try f.symbol("dos64_address");f.poke(a,@truncate(at));f.poke(a+1,@truncate(at>>8));f.poke(a+2,@truncate(at>>16));f.poke(try f.symbol("dos64_mem_value"),v);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_mem_write",100000)).p&1);}
pub fn busRead(f:*F,at:u32)!u8{const a=try f.symbol("dos64_address");f.poke(a,@truncate(at));f.poke(a+1,@truncate(at>>8));f.poke(a+2,@truncate(at>>16));const r=try f.call("dos64_mem_read",100000);try std.testing.expectEqual(@as(u8,0),r.p&1);return r.a;}
pub fn acquire(f:*F,id:u8)!void{f.poke(try f.symbol("dos64_overlay_requested"),id);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_acquire",100000)).p&1);}
pub fn release(f:*F)!void{try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_release",10000)).p&1);}

test "AH05 accepts raw saved cursor bytes after page change and programs full14bit physical cursor"{
 var f=try init();defer f.deinit();try video(&f,3,0,0,0);try busWrite(&f,0x452,255);try busWrite(&f,0x453,255);try video(&f,0x0501,0,0,0);const rr=try f.symbol("dos64_cga_registers");try std.testing.expectEqual(@as(u8,1),try busRead(&f,0x462));try std.testing.expectEqual(@as(u8,0x10),try busRead(&f,0x44f));try std.testing.expectEqual(@as(u8,8),f.peek(rr+12));try std.testing.expectEqual(@as(u8,0x18),f.peek(rr+14));try std.testing.expectEqual(@as(u8,0xaf),f.peek(rr+15));try std.testing.expectEqual(@as(u8,255),try busRead(&f,0x452));
}
test "CGA modecontrol is6bit writeonly and supports blank blink intensity only within BIOS geometry atomically"{
 var f=try init();defer f.deinit();const ctl=try f.symbol("dos64_cga_control");_=try io(&f,false,0x3d8,0,0x21,false);try video(&f,3,0,0,0);try std.testing.expectEqual(@as(u8,0x29),f.peek(ctl));
 for([_]u8{0x21,0x29,0x09,0xc9,0x01,0x29})|value|{_=try io(&f,false,0x3d8,0,value,true);try std.testing.expectEqual(value&0x3f,f.peek(ctl));try std.testing.expectEqual(@as(u8,0x29),try busRead(&f,0x465));}
 for([_]u8{0x28,0x2b,0x2d,0x39})|value|{_=try io(&f,false,0x3d8,0,value,false);try std.testing.expectEqual(@as(u8,0x29),f.peek(ctl));}
 _=try io(&f,true,0x3d8,0,0x12ab,false);_=try io(&f,false,0x3d8,1,0x2121,false);try std.testing.expectEqual(@as(u8,0x29),f.peek(ctl));_=try f.call("dos64_io_init",10000);try std.testing.expectEqual(@as(u8,0),f.peek(try f.symbol("dos64_cga_control_valid")));
}
fn renderReady(f:*F)!void{f.poke(try f.symbol("dos64_cache_limit"),32);_=try f.call("dos64_cache_init",50000);_=try f.call("dos64_bios_init",40000000);_=try f.call("dos64_cache_flush",2000000);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_cold_release",10000)).p&1);f.poke(try f.symbol("dos64_cache_limit"),2);_=try f.call("dos64_cache_init",50000);}

test "CGA text blanking paintsblack without guest VRAM mutation and intensity disables glyphblink"{
 var f=try init();defer f.deinit();try renderReady(&f);try video(&f,1,0,0,0);for(0..8)|n|f.poke(0x4800+0x41*8+@as(u16,@intCast(n)),255);try busWrite(&f,0xb8000,0x41);try busWrite(&f,0xb8001,0x87);const request=try f.symbol("dos64_render_text_request");f.poke(request,0);f.poke(request+1,0);
 try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);try std.testing.expectEqual(@as(u8,0),f.peek(0x6000));try std.testing.expectEqual(@as(u8,0xf0),f.peek(0x4000));
 _=try io(&f,false,0x3d8,0,0x08,true);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);try std.testing.expectEqual(@as(u8,255),f.peek(0x6000));try std.testing.expectEqual(@as(u8,0xfc),f.peek(0x4000));
 _=try io(&f,false,0x3d8,0,0x00,true);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);for(0..40)|n|try std.testing.expectEqual(@as(u8,0),f.peek(0x4000+@as(u16,@intCast(n))));try std.testing.expectEqual(@as(u8,255),f.peek(0x6000));try std.testing.expectEqual(@as(u8,0x41),try busRead(&f,0xb8000));try std.testing.expectEqual(@as(u8,0x87),try busRead(&f,0xb8001));
 _=try io(&f,false,0x3d8,0,0x28,true);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);try std.testing.expectEqual(@as(u8,0xf0),f.peek(0x4000));try std.testing.expectEqual(@as(u8,0),f.peek(0x6000));
}
test "CGA graphicsblank emitsblack matrix colorRAM and background while preserving source bitmap and restoresenabledpalette"{
 for([_]u8{4,6})|mode|{var f=try init();defer f.deinit();try renderReady(&f);gm.dos64_graphics_color_enable(@ptrCast(f.machine));try video(&f,mode,0,0,0);try busWrite(&f,0xb8000,255);try acquire(&f,5);const r=try f.symbol("dos64_render_graphics_request");f.poke(r,0);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_render_graphics_line",500000)).p&1);const visible=f.peek(0x4000);try std.testing.expect(visible!=0);const bits=f.peek(0x6000);try release(&f);const ctl=f.peek(try f.symbol("dos64_cga_control"));_=try io(&f,false,0x3d8,0,ctl&0xf7,true);try acquire(&f,5);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_render_graphics_line",500000)).p&1);try std.testing.expectEqual(@as(u8,0),f.peek(0x4000));try std.testing.expectEqual(@as(u8,0),f.peek(r+4));if(mode==4)try std.testing.expectEqual(@as(u8,0),gm.dos64_graphics_color_peek(@ptrCast(f.machine),0xd800));try std.testing.expectEqual(bits,f.peek(0x6000));try release(&f);try std.testing.expectEqual(@as(u8,255),try busRead(&f,0xb8000));_=try io(&f,false,0x3d8,0,ctl,true);try acquire(&f,5);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_render_graphics_line",500000)).p&1);try std.testing.expectEqual(visible,f.peek(0x4000));try release(&f);}
}
